def standard():
    tbl = {1.0: Rational('0.341'), 1.5: Rational('0.433'), 2.0: Rational('0.477'), 2.5: Rational('0.494')}
    n = 4050
    # 한 번 시행의 이동량 분포: 눈 1,2 → +2, 눈 3~6 → -1
    steps = [2 if k <= 2 else -1 for k in range(1, 7)]
    m1 = Rational(sum(steps), 6)
    v1 = Rational(sum(s**2 for s in steps), 6) - m1**2
    mean, sd = n*m1, sqrt(n*v1)
    z = (135 - mean) / sd
    return 1000*(Rational(1, 2) - tbl[float(z)])

def unique():
    return [standard()]
